import{_ as l,a0 as p,w as o,s as d,ao as c,I as t,x as i,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何在 RHEL 8 上安装 MiniKube | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 8 上安装 MiniKube | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 RHEL 8 上安装 MiniKube | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 8 上安装 MiniKube | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230308.2 ⭐️⭐️ How to Install MiniKube on RHEL 8Rocky Linux 8AlmaLinux 8","title":"如何在 RHEL 8 上安装 MiniKube","tag":"202303","desc":""},"relativePath":"202303/20230308.2 ⭐️⭐️ How to Install MiniKube on RHEL 8Rocky Linux 8AlmaLinux 8.md","filePath":"[post].md"}'),r={name:"202303/20230308.2 ⭐️⭐️ How to Install MiniKube on RHEL 8Rocky Linux 8AlmaLinux 8.md"};function u(h,s,k,b,g,m){const e=p("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="如何在-rhel-8-上安装-minikube" tabindex="-1">如何在 RHEL 8 上安装 MiniKube <a class="header-anchor" href="#如何在-rhel-8-上安装-minikube" aria-label="Permalink to “如何在 RHEL 8 上安装 MiniKube”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202303/15/232024hn8312yg1qmy7mhv.jpg" alt=""></p><blockquote><p>在这篇文章中，我们将逐步介绍如何在 RHEL 8、Rocky Linux 8 或 AlmaLinux 8 上安装 MiniKube。</p></blockquote><p>MiniKube 是一个跨平台的开源工具，可以让你在本地机器上部署单节点 Kubernetes 集群。</p><p>Kubernetes，也被称为 k8s，或简称 Kube，是一个开源的容器编排平台，用于容器的自动化扩展和部署。MiniKube 集群帮助开发人员和管理员在集群中构建他们的测试环境。</p><h5 id="minikube-的先决条件" tabindex="-1">MiniKube 的先决条件 <a class="header-anchor" href="#minikube-的先决条件" aria-label="Permalink to “MiniKube 的先决条件”">​</a></h5><ul><li>最小化安装的 RHEL 8 或 Rocky Linux 8 或 AlmaLinux 8</li><li>本地配置的 RHEL 8 仓库或订阅</li><li>至少 2GB RAM 和 2 个 vCPU</li><li>20GB 硬盘空间</li><li>具有管理员身份的 sudo 用户</li><li>稳定的互联网连接</li><li>Docker 或虚拟机管理器，如 VirtualBox、KVM 和 VMware 等</li></ul><p>在这篇文章中，我们将使用 Docker 作为 MiniKube 的驱动程序。满足所有先决条件后，现在是时候卷起袖子动手了。</p><h3 id="步骤-1-启用官方-docker-仓库" tabindex="-1">步骤 1）启用官方 Docker 仓库 <a class="header-anchor" href="#步骤-1-启用官方-docker-仓库" aria-label="Permalink to “步骤 1）启用官方 Docker 仓库”">​</a></h3><p>要启用 Docker 官方仓库，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf config-manager --add-repo=https://download.docker.com/linux/centos/docker-ce.repo</span></span>
<span class="line"><span>$ sudo dnf repolist</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Enable-Docker-Repo-RHEL8-Rocky-Linux8-1024x203.png" alt=""></p><h3 id="步骤-2-安装-docker-ce-社区版" tabindex="-1">步骤 2）安装 Docker CE（社区版） <a class="header-anchor" href="#步骤-2-安装-docker-ce-社区版" aria-label="Permalink to “步骤 2）安装 Docker CE（社区版）”">​</a></h3><p>运行以下 <code>dnf</code> 命令来安装 Docker 及其依赖项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install docker-ce docker-ce-cli containerd.io -y</span></span></code></pre></div><p>输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Install-Docker-DNF-Command-RHEL8-RockyLinux8.png" alt=""></p><p>安装 Docker 后启动并启用它的服务，运行以下 <code>systemctl</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start docker</span></span>
<span class="line"><span>$ sudo systemctl start docker</span></span></code></pre></div><p>允许你的本地用户在没有 <code>sudo</code> 的情况下运行 <code>docker</code> 命令，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -aG docker $USER</span></span>
<span class="line"><span>$ newgrp docker</span></span></code></pre></div><h3 id="步骤-3-安装-kubectl-二进制文件" tabindex="-1">步骤 3）安装 kubectl 二进制文件 <a class="header-anchor" href="#步骤-3-安装-kubectl-二进制文件" aria-label="Permalink to “步骤 3）安装 kubectl 二进制文件”">​</a></h3><p><code>kubectl</code> 是一个命令行工具，它通过 API 与 Kubernetes 集群进行交互。我们使用 <code>kubectl</code> 部署应用。默认情况下，<code>kubectl</code> 不包含在 RHEL 8 、Rocky Linux 8 或 AlmaLinux 8 软件包仓库中。因此，我们将使用下面的命令手动安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -LO &quot;https://dl.k8s.io/release/$(curl -L -s https://dl.k8s.io/release/stable.txt)/bin/linux/amd64/kubectl&quot;</span></span>
<span class="line"><span>$ sudo cp kubectl /usr/local/bin/ &amp;&amp; sudo chmod +x /usr/local/bin/kubectl</span></span>
<span class="line"><span>$ kubectl version --client</span></span></code></pre></div><p>以上命令的输出如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Download-Kubectl-Binary-RHEL8-RockyLinux8.png" alt=""></p><h3 id="步骤-4-下载-minikube-二进制文件并启动集群" tabindex="-1">步骤 4）下载 MiniKube 二进制文件并启动集群 <a class="header-anchor" href="#步骤-4-下载-minikube-二进制文件并启动集群" aria-label="Permalink to “步骤 4）下载 MiniKube 二进制文件并启动集群”">​</a></h3><p>安装 <code>kubectl</code> 后，让我们使用以下命令下载并安装 MiniKube 二进制文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -LO https://storage.googleapis.com/minikube/releases/latest/minikube-linux-amd64</span></span>
<span class="line"><span>$ sudo install minikube-linux-amd64 /usr/local/bin/minikube</span></span></code></pre></div><p>现在使用下面的命令启动 MiniKube 集群：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube start --driver docker</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Start-Minikube-Cluster-RHEL8-Rocky-Linux8.png" alt=""></p><p>上面的输出确认 <code>minikube</code> 命令已经使用 <code>docker</code> 作为驱动程序启动了单节点 Kubernetes 集群。</p><p>运行下面的 <code>minikube</code> 命令来验证本地 Kubernetes 集群的状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube status</span></span>
<span class="line"><span>minikube</span></span>
<span class="line"><span>type: Control Plane</span></span>
<span class="line"><span>host: Running</span></span>
<span class="line"><span>kubelet: Running</span></span>
<span class="line"><span>apiserver: Running</span></span>
<span class="line"><span>kubeconfig: Configured</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ minikube ip</span></span>
<span class="line"><span>192.168.49.2</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>要停止 MiniKube 集群，请执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube stop</span></span></code></pre></div><p>执行 <code>kubectl</code> 命令查看集群和节点信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl cluster-info</span></span>
<span class="line"><span>$ kubectl get nodes</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/K8s-cluster-info-RHEL8-RockyLinux9-1024x193.png" alt=""></p><h3 id="步骤-5-测试和验证-kubernetes-集群" tabindex="-1">步骤 5）测试和验证 Kubernetes 集群 <a class="header-anchor" href="#步骤-5-测试和验证-kubernetes-集群" aria-label="Permalink to “步骤 5）测试和验证 Kubernetes 集群”">​</a></h3><p>为了测试 Kubernetes 集群，让我们尝试使用 echo 服务器镜像创建 k8s 部署，它相当于 HTTP Web 服务器并将其作为服务暴露在端口 8080 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl create deployment test-minikube --image=k8s.gcr.io/echoserver:1.10</span></span>
<span class="line"><span>deployment.apps/test-minikube created</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>要访问 <code>test-minikube</code> 部署，将其公开为服务，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl expose deployment test-minikube --type=NodePort --port=8080</span></span>
<span class="line"><span>service/test-minikube exposed</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>运行以下 <code>kubectl</code> 命令以获取上面创建的部署、<ruby>容器荚<rt>pod</rt></ruby> 和服务信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get deployment,pods,svc</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Kubectl-get-pods-deplyments-service-rhel8-rocky-linux8.png" alt=""></p><p>要访问服务，请通过运行下面的命令获取其 URL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube service test-minikube --url</span></span>
<span class="line"><span>http://192.168.49.2:32291</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ curl http://192.168.49.2:32291/</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Access-Application-minikube-rhel8-rockylinux8.png" alt=""></p><p>太好了，这意味着我们的 Kubernetes 集群工作正常，因为我们能够访问我们的示例应用。</p><h5 id="步骤-6-启用-minikube-插件" tabindex="-1">步骤 6）启用 MiniKube 插件 <a class="header-anchor" href="#步骤-6-启用-minikube-插件" aria-label="Permalink to “步骤 6）启用 MiniKube 插件”">​</a></h5><p>MiniKube 提供插件，可以为我们的集群添加额外的功能。要列出所有可用的插件，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube addons list</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/minikube-addons-list-rhel8-rockylinux8.png" alt=""></p><p>Kubernetes 附带一个仪表板，可让你管理集群。在 MiniKube 中，仪表板已作为插件添加。所以要启用它，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube addons enable dashboard</span></span></code></pre></div><p>还要启用 nginx 入口控制器，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube addons enable ingress</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Enable-Minikube-addons-RHEL8-RockyLinux9-1024x381.png" alt=""></p><p>要访问仪表板，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube dashbaord --url</span></span></code></pre></div><p>这将在你系统的浏览器中启动仪表板。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Kubernetes-Dashboard-MiniKube-Dashboard.png" alt=""></p><p>就是这些了。我们已经成功地在 RHEL 8、Rocky Linux 8 或 AlmaLinux 8 上使用 MiniKube 安装了 Kubernetes。欢迎你在下面的评论部分分享你的反馈和意见。</p><hr>`,67)),t("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.linuxtechi.com/install-minikube-on-rhel-rockylinux-almalinux/"},{default:n(()=>[...s[0]||(s[0]=[i("https://www.linuxtechi.com/install-minikube-on-rhel-rockylinux-almalinux/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=i("作者：",-1)),a(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...s[2]||(s[2]=[i("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=i(" 选题：",-1)),a(e,{href:"https://github.com/lkxed/"},{default:n(()=>[...s[3]||(s[3]=[i("lkxed",-1)])]),_:1}),s[8]||(s[8]=i(" 译者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:n(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[i("Linux中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const w=l(r,[["render",u]]);export{y as __pageData,w as default};
